  const modelOpts = (isAlt, isFP8) => ({ fill: { color: isAlt ? C.tableRowAlt : C.white }, color: isFP8 ? C.slate500 : C.textDark, fontSize: 9, fontFace: FONT_BODY, align: "left", valign: "middle", margin: [2, 6, 2, 6], bold: !isFP8 });

