    [{ text: "Llama-3-8B-Instruct", options: modelOpts(false, false) }, { text: "62.69 ± 0.18", options: cellOpts(false) }, { text: "61.14 ± 3.47", options: cellOpts(false) }, { text: "20.65 ± 3.43", options: cellOpts(false) }, { text: "22.62 ± 0.22", options: cellOpts(false) }],
    [{ text: "  → FP8", options: modelOpts(false, true) }, { text: "62.43 ± 0.26", options: cellOpts(false) }, { text: "60.90 ± 4.10", options: cellOpts(false) }, { text: "14.91 ± 2.49", options: cellOpts(false) }, { text: "20.14 ± 0.24", options: cellOpts(false) }],
    // Llama-3-70B
    [{ text: "Llama-3-70B-Instruct", options: modelOpts(true, false) }, { text: "78.05 ± 0.08", options: cellOpts(true) }, { text: "88.06 ± 1.44", options: cellOpts(true) }, { text: "35.69 ± 1.33", options: cellOpts(true) }, { text: "29.60 ± 0.51", options: cellOpts(true) }],
    [{ text: "  → FP8", options: modelOpts(true, true) }, { text: "77.88 ± 0.13", options: cellOpts(true) }, { text: "87.35 ± 1.24", options: cellOpts(true) }, { text: "35.75 ± 1.16", options: cellOpts(true) }, { text: "33.12 ± 0.30", options: cellOpts(true) }],
    // Gemma-2-9b
    [{ text: "Gemma-2-9b-it", options: modelOpts(false, false) }, { text: "71.86 ± 0.08", options: cellOpts(false) }, { text: "81.80 ± 1.35", options: cellOpts(false) }, { text: "33.41 ± 0.28", options: cellOpts(false) }, { text: "28.64 ± 2.97", options: cellOpts(false) }],
    [{ text: "  → FP8", options: modelOpts(false, true) }, { text: "71.92 ± 0.11", options: cellOpts(false) }, { text: "79.41 ± 1.14", options: cellOpts(false) }, { text: "32.53 ± 0.34", options: cellOpts(false) }, { text: "27.81 ± 3.22", options: cellOpts(false) }],
