    [{ text: "Qwen2-72B-Instruct", options: modelOpts(true, false) }, { text: "82.18 ± 0.08", options: cellOpts(true) }, { text: "86.72 ± 1.00", options: cellOpts(true) }, { text: "37.39 ± 1.41", options: cellOpts(true) }, { text: "29.93 ± 2.71", options: cellOpts(true) }],
    [{ text: "  → FP8", options: modelOpts(true, true) }, { text: "81.98 ± 0.08", options: cellOpts(true) }, { text: "86.82 ± 0.97", options: cellOpts(true) }, { text: "37.67 ± 1.39", options: cellOpts(true) }, { text: "31.08 ± 1.96", options: cellOpts(true) }],
    // Mistral-7B
    [{ text: "Mistral-7B-Instruct-v0.3", options: modelOpts(false, false) }, { text: "59.15 ± 0.10", options: cellOpts(false) }, { text: "35.90 ± 4.54", options: cellOpts(false) }, { text: "8.94 ± 1.24", options: cellOpts(false) }, { text: "21.60 ± 0.17", options: cellOpts(false) }],
    [{ text: "  → FP8", options: modelOpts(false, true) }, { text: "58.77 ± 0.13", options: cellOpts(false) }, { text: "32.20 ± 4.02", options: cellOpts(false) }, { text: "7.68 ± 1.23", options: cellOpts(false) }, { text: "22.72 ± 0.19", options: cellOpts(false) }],
