  });

  slide.addText([
    { text: "As p → 0, the mixed distribution ", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700 } },
    { text: "converges to P_spec", options: { fontSize: 11, fontFace: FONT_BODY, color: C.redMuted, bold: true } },
