  // Hypothesis testing framework box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.7, w: 8.8, h: 0.7,
    fill: { color: C.darkBg }
  });
  slide.addText([
    { text: "Formal Framework:  ", options: { bold: true, color: C.accent, fontSize: 11, fontFace: FONT_HEADER } },
    { text: "H₀: P(y|x) = P_spec(y|x)   vs   H₁: P(y|x) = P_actual(y|x)", options: { color: C.textLight, fontSize: 12, fontFace: FONT_BODY } },
  ], {
    x: 0.85, y: 4.7, w: 8.35, h: 0.7,
    align: "left", valign: "middle", margin: 0
  });
}

