) }],\n    [{ text: \"  → FP8\", options: modelOpts(true, true) }, { text: \"77.88 ± 0.13\", options: cellOpts(true) }, { text: \"87.35 ± 1.24\", options: cellOpts(true) }, { text: \"35.75 ± 1.16\", options: cellOpts(true) }, { text: \"33.12 ± 0.30\", options: cellOpts(true) }],\n    // Gemma-2-9b\n    [{ text: \"Gemma-2-9b-it\", options: modelOpts(false, false) }, { text: \"71.86 ± 0.08\", options: cellOpts(false) }, { text: \"81.80 ± 1.35\", options: cellOpts(false) }, { text: \"33.41 ± 0.28\", options: cellOpts(false) }, { text: \"28.64 ± 2.97\", options: cellOpts(false) }],\n    [{ text: \"  → FP8\", options: modelOpts(false, true) }, { text: \"71.92 ± 0.11\", options: cellOpts(false) }, { text: \"79.41 ± 1.14\", options: cellOpts(false) }, { text: \"32.53 ± 0.34\", options: cellOpts(false) }, { text: \"27.81 ± 3.22\", options: cellOpts(false) }],\n    // Qwen2-72B\n    [{ text: \"Qwen2-72B-Instruct\", options: modelOpts(true, false) }, { text: \"82.18 ± 0.08\", options: cellOpts(true) }, { text: \"86.72 ± 1.00\", options: cellOpts(true) }, { text: \"37.39 ± 1.41\", options: cellOpts(true) }, { text: \"29.93 ± 2.71\", options: cellOpts(true) }],\n    [{ text: \"  → FP8\", options: modelOpts(true, true) }, { text: \"81.98 ± 0.08\", options: cellOpts(true) }, { text: \"86.82 ± 0.97\", options: cellOpts(true) }, { text: \"37.67 ± 1.39\", options: cellOpts(true) }, { text: \"31.08 ± 1.96\", options: cellOpts(true) }],\n    // Mistral-7B\n    [{ text: \"Mistral-7B-Instruct-v0.3\", options: modelOpts(false, false) }, { text: \"59.15 ± 0.10\", options: cellOpts(false) }, { text: \"35.90 ± 4.54\", options: cellOpts(false) }, { text: \"8.94 ± 1.24\", options: cellOpts(false) }, { text: \"21.60 ± 0.17\", options: cellOpts(false) }],\n    [{ text: \"  → FP8\", options: modelOpts(false, true) }, { text: \"58.77 ± 0.13\", options: cellOpts(false) }, { text: \"32.20 ± 4.02\", options: cellOpts(false) }, { text: \"7.68 ± 1.23\", options: cellOpts(false) }, { text: \"22.72 ± 0.19\", options: cellOpts(false) }],\n  ];\n\n  slide.addTable(rows, {\n    x: 0.5, y: 1.3, w: 9.0,\n    colW: [2.6, 1.6, 1.6, 1.6, 1.6],\n    border: { pt: 0.5, color: C.slate300 },\n    rowH: [0.3, 0.27, 0.27, 0.27, 0.27, 0.27, 0.27, 0.27, 0.27, 0.27, 0.27],\n  });\n\n  // Key insight callout\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.65, w: 9.0, h: 0.7,\n    fill: { color: C.accentLight }, shadow: makeSubtleShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.65, w: 0.06, h: 0.7,\n    fill: { color: C.accent }\n  });\n  slide.addText([\n    { text: \"Key Insight: \", options: { bold: true, color: C.accentDark, fontSize: 11, fontFace: FONT_HEADER } },\n    { text: \"For most models, FP8 scores fall within the error bars of the original, especially on MMLU and GSM8K. Quantization saves significant GPU costs while being nearly undetectable via benchmark comparison.\", options: { color: C.slate700, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.75, y: 4.65, w: 8.55, h: 0.7,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n}\n\n// ─── SLIDE 4: Temperature Scaling ───\nfunction buildSlide4() {\n  const slide = pres.addSlide();\n  slide.background = { color: C.lightBg };\n\n  slide.addText(\"Higher Temperature Amplifies Gaps but Increases Noise\", {\n    x: 0.6, y: 0.3, w: 9, h: 0.55,\n    fontSize: 26, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  // Image\n  const imgPath = path.resolve(\"/app/benchmark/assets/figure_1.jpg\");\n  slide.addImage({\n    path: imgPath,\n    x: 0.5, y: 1.05, w: 6.2, h: 3.5,\n    sizing: { type: \"contain\", w: 6.2, h: 3.5 }\n  });\n\n  // Side panel with key points\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.0, y: 1.05, w: 2.6, h: 3.5,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.0, y: 1.05, w: 0.06, h: 3.5,\n    fill: { color: C.accent }\n  });\n\n  slide.addText(\"Key Observations\", {\n    x: 7.25, y: 1.15, w: 2.2, h: 0.35,\n    fontSize: 13, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  slide.addText([\n    { text: \"Temperature 0.2–0.5: \", options: { bold: true, fontSize: 10, fontFace: FONT_BODY, color: C.textDark } },\n    { text: \"Performance gaps between original and FP8 models are small\", options: { fontSize: 10, fontFace: FONT_BODY, color: C.slate600 } },\n    { text: \"\", options: { breakLine: true, fontSize: 6 } },\n    { text: \"Temperature 1.0: \", options: { bold: true, fontSize: 10, fontFace: FONT_BODY, color: C.textDark } },\n    { text: \"All models degrade; substitution signal weakens\", options: { fontSize: 10, fontFace: FONT_BODY, color: C.slate600 } },\n    { text: \"\", options: { breakLine: true, fontSize: 6 } },\n    { text: \"Temperature 2.0: \", options: { bold: true, fontSize: 10, fontFace: FONT_BODY, color: C.redMuted } },\n    { text: \"Severe degradation across all models; gap narrows or becomes noisy, complicating statistical detection\", options: { fontSize: 10, fontFace: FONT_BODY, color: C.slate600 } },\n  ], {\n    x: 7.25, y: 1.55, w: 2.2, h: 2.8,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Bottom insight\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 9.0, h: 0.55,\n    fill: { color: C.amberBg }\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 0.06, h: 0.55,\n    fill: { color: C.amber }\n  });\n  slide.addText([\n    { text: \"Implication: \", options: { bold: true, color: C.redMuted, fontSize: 11, fontFace: FONT_HEADER } },\n    { text: \"Higher temperatures do not reliably amplify the substitution signal — they increase variance, making statistical detection even harder.\", options: { color: C.slate700, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.75, y: 4.8, w: 8.55, h: 0.55,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n\n  // Source caption\n  slide.addText(\"Source: arxiv.org/abs/2504.04715, Figure 1\", {\n    x: 0.5, y: 5.3, w: 9.0, h: 0.25,\n    fontSize: 8, fontFace: FONT_BODY, color: C.slate400,\n    align: \"left\", margin: 0\n  });\n}\n\n// ─── SLIDE 5: Log-Prob Nondeterminism ───\nfunction buildSlide5() {\n  const slide = pres.addSlide();\n  slide.background = { color: C.lightBg };\n\n  slide.addText(\"Log Probability Fingerprinting Fails\", {\n    x: 0.6, y: 0.3, w: 9, h: 0.55,\n    fontSize: 26, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n  slide.addText(\"Due to Inference Nondeterminism\", {\n    x: 0.6, y: 0.82, w: 9, h: 0.35,\n    fontSize: 15, fontFace: FONT_BODY, color: C.slate500, italic: true,\n    align: \"left\", margin: 0\n  });\n\n  // Image\n  const imgPath = path.resolve(\"/app/benchmark/assets/figure_5.jpg\");\n  slide.addImage({\n    path: imgPath,\n    x: 0.5, y: 1.3, w: 6.2, h: 3.2,\n    sizing: { type: \"contain\", w: 6.2, h: 3.2 }\n  });\n\n  // Side panel\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.0, y: 1.3, w: 2.6, h: 3.2,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.0, y: 1.3, w: 0.06, h: 3.2,\n    fill: { color: C.red }\n  });\n\n  slide.addText(\"Sources of Variation\", {\n    x: 7.25, y: 1.4, w: 2.2, h: 0.35,\n    fontSize: 13, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  // Software variation\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.25, y: 1.85, w: 2.15, h: 0.9,\n    fill: { color: C.redBg }\n  });\n  slide.addText([\n    { text: \"Software Frameworks\", options: { bold: true, fontSize: 10, fontFace: FONT_HEADER, color: C.redMuted } },\n    { text: \"\", options: { breakLine: true, fontSize: 4 } },\n    { text: \"transformers 4.40 vs 4.50\", options: { fontSize: 9, fontFace: FONT_BODY, color: C.slate600 } },\n    { text: \"vLLM 0.6.2 vs 0.8.2\", options: { fontSize: 9, fontFace: FONT_BODY, color: C.slate600 } },\n  ], {\n    x: 7.35, y: 1.9, w: 1.95, h: 0.8,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Hardware variation\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.25, y: 2.9, w: 2.15, h: 0.65,\n    fill: { color: C.amberBg }\n  });\n  slide.addText([\n    { text: \"GPU Hardware\", options: { bold: true, fontSize: 10, fontFace: FONT_HEADER, color: C.amber } },\n    { text: \"\", options: { breakLine: true, fontSize: 4 } },\n    { text: \"NVIDIA A100 vs H100\", options: { fontSize: 9, fontFace: FONT_BODY, color: C.slate600 } },\n  ], {\n    x: 7.35, y: 2.95, w: 1.95, h: 0.55,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Bottom callout\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.25, y: 3.7, w: 2.15, h: 0.65,\n    fill: { color: C.darkBg }\n  });\n  slide.addText([\n    { text: \"Result: \", options: { bold: true, fontSize: 10, fontFace: FONT_HEADER, color: C.accent } },\n    { text: \"Cannot distinguish legitimate infrastructure differences from actual substitution\", options: { fontSize: 9, fontFace: FONT_BODY, color: C.textLight } },\n  ], {\n    x: 7.35, y: 3.75, w: 1.95, h: 0.55,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n\n  // Bottom insight\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 9.0, h: 0.55,\n    fill: { color: C.redBg }\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 0.06, h: 0.55,\n    fill: { color: C.red }\n  });\n  slide.addText([\n    { text: \"Core Problem: \", options: { bold: true, color: C.redMuted, fontSize: 11, fontFace: FONT_HEADER } },\n    { text: \"Production-level nondeterminism defeats metadata-based detection. An auditor cannot tell if log-prob differences come from a substituted model or simply a different inference stack.\", options: { color: C.slate700, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.75, y: 4.8, w: 8.55, h: 0.55,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n\n  slide.addText(\"Source: arxiv.org/abs/2504.04715, Figure 5\", {\n    x: 0.5, y: 5.3, w: 9.0, h: 0.25,\n    fontSize: 8, fontFace: FONT_BODY, color: C.slate400,\n    align: \"left\", margin: 0\n  });\n}\n\n// ─── SLIDE 6: Randomized Substitution ───\nfunction buildSlide6(icons) {\n  const slide = pres.addSlide();\n  slide.background = { color: C.lightBg };\n\n  slide.addText(\"Randomized Routing Makes Detection Query-Prohibitive\", {\n    x: 0.6, y: 0.3, w: 9, h: 0.55,\n    fontSize: 26, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  // Attack description card\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 1.1, w: 4.2, h: 2.0,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 1.1, w: 0.06, h: 2.0,\n    fill: { color: C.red }\n  });\n\n  slide.addText(\"The Attack\", {\n    x: 0.85, y: 1.15, w: 3.75, h: 0.35,\n    fontSize: 14, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  slide.addText([\n    { text: \"Provider routes only a fraction \", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700 } },\n    { text: \"p\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.redMuted, italic: true, bold: true } },\n    { text: \" of queries to the cheaper substitute model. The remaining (1−p) queries go to the genuine model.\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700 } },\n  ], {\n    x: 0.85, y: 1.55, w: 3.75, h: 0.8,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  slide.addText([\n    { text: \"As p → 0, the mixed distribution \", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700 } },\n    { text: \"converges to P_spec\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.redMuted, bold: true } },\n    { text: \", requiring exponentially more queries to detect the substitution.\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700 } },\n  ], {\n    x: 0.85, y: 2.4, w: 3.75, h: 0.6,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Visual: mixing diagram\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 5.2, y: 1.1, w: 4.3, h: 2.0,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n\n  // Specified model box\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 5.5, y: 1.3, w: 1.6, h: 0.55,\n    fill: { color: C.accentLight }\n  });\n  slide.addText(\"P_spec (genuine)\", {\n    x: 5.5, y: 1.3, w: 1.6, h: 0.55,\n    fontSize: 10, fontFace: FONT_BODY, color: C.accentDark, bold: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  // Substitute model box\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 7.6, y: 1.3, w: 1.6, h: 0.55,\n    fill: { color: C.redBg }\n  });\n  slide.addText(\"P_sub (cheaper)\", {\n    x: 7.6, y: 1.3, w: 1.6, h: 0.55,\n    fontSize: 10, fontFace: FONT_BODY, color: C.redMuted, bold: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  // Arrows down\n  slide.addText(\"(1−p)\", {\n    x: 5.8, y: 1.9, w: 0.9, h: 0.3,\n    fontSize: 12, fontFace: FONT_BODY, color: C.accentDark, bold: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n  slide.addShape(pres.shapes.LINE, {\n    x: 6.3, y: 1.9, w: 0, h: 0.25,\n    line: { color: C.accentDark, width: 1.5 }\n  });\n  slide.addText(\"p\", {\n    x: 8.0, y: 1.9, w: 0.6, h: 0.3,\n    fontSize: 12, fontFace: FONT_BODY, color: C.redMuted, bold: true, italic: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n  slide.addShape(pres.shapes.LINE, {\n    x: 8.4, y: 1.9, w: 0, h: 0.25,\n    line: { color: C.redMuted, width: 1.5 }\n  });\n\n  // Mixed output\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 6.0, y: 2.3, w: 2.7, h: 0.55,\n    fill: { color: C.darkBg }\n  });\n  slide.addText(\"Mixed Distribution ≈ P_spec as p→0\", {\n    x: 6.0, y: 2.3, w: 2.7, h: 0.55,\n    fontSize: 10, fontFace: FONT_BODY, color: C.textLight,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  // Benchmark evasion card\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 3.4, w: 8.9, h: 1.1,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 3.4, w: 0.06, h: 1.1,\n    fill: { color: C.amber }\n  });\n\n  slide.addText(\"Adversarial Strategy #2: Benchmark Evasion\", {\n    x: 0.85, y: 3.45, w: 8.4, h: 0.35,\n    fontSize: 13, fontFace: FONT_HEADER, color: C.amber, bold: true,\n    align: \"left\", margin: 0\n  });\n  slide.addText(\"Provider detects known benchmark prompts and routes them to the genuine model while serving substitutes for regular traffic. Audits using standard benchmarks are trivially evaded.\", {\n    x: 0.85, y: 3.85, w: 8.4, h: 0.55,\n    fontSize: 11, fontFace: FONT_BODY, color: C.slate700,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Bottom callout\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 9.0, h: 0.55,\n    fill: { color: C.redBg }\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.8, w: 0.06, h: 0.55,\n    fill: { color: C.red }\n  });\n  slide.addText([\n    { text: \"Combined Effect: \", options: { bold: true, color: C.redMuted, fontSize: 11, fontFace: FONT_HEADER } },\n    { text: \"Randomized substitution + benchmark evasion make software-only detection fundamentally query-prohibitive, even with infinite query budgets.\", options: { color: C.slate700, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.75, y: 4.8, w: 8.55, h: 0.55,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n}\n\n// ─── SLIDE 7: Software Methods Summary ───\nfunction buildSlide7() {\n  const slide = pres.addSlide();\n  slide.background = { color: C.lightBg };\n\n  slide.addText(\"Software-Only Auditing Methods Are Fundamentally Unreliable\", {\n    x: 0.5, y: 0.3, w: 9.2, h: 0.55,\n    fontSize: 24, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n\n  // Comparison matrix table\n  const hdrOpts = { fill: { color: C.darkBg }, color: C.white, bold: true, fontSize: 11, fontFace: FONT_HEADER, align: \"center\", valign: \"middle\", margin: [4, 6, 4, 6] };\n  const catOpts = { fill: { color: C.white }, color: C.textDark, bold: true, fontSize: 10, fontFace: FONT_BODY, align: \"left\", valign: \"middle\", margin: [4, 8, 4, 8] };\n  const cellOpts = (isAlt) => ({ fill: { color: isAlt ? C.tableRowAlt : C.white }, color: C.slate700, fontSize: 10, fontFace: FONT_BODY, align: \"left\", valign: \"middle\", margin: [4, 8, 4, 8] });\n\n  const tableData = [\n    [\n      { text: \"Method Type\", options: { ...hdrOpts, align: \"left\" } },\n      { text: \"Core Weakness\", options: hdrOpts },\n      { text: \"Practical Limitation\", options: hdrOpts },\n    ],\n    [\n      { text: \"Text-Based Statistical Tests\\n(e.g., MMD)\", options: catOpts },\n      { text: \"Requires impractically large query budgets; fails against subtle substitutions\", options: cellOpts(false) },\n      { text: \"Even with millions of queries, cannot reliably distinguish FP8 from FP16 when differences fall within error bars\", options: cellOpts(false) },\n    ],\n    [\n      { text: \"Log-Probability Fingerprinting\", options: { ...catOpts, fill: { color: C.tableRowAlt } } },\n      { text: \"Defeated by production-level inference nondeterminism across software versions and GPU hardware\", options: cellOpts(true) },\n      { text: \"Cannot distinguish legitimate infrastructure differences from actual model substitution\", options: cellOpts(true) },\n    ],\n    [\n      { text: \"Adversarial Countermeasures\\n(Randomized routing,\\nBenchmark evasion)\", options: { ...catOpts, fill: { color: C.white } } },\n      { text: \"Providers actively evade audits by mixing substitute responses or detecting benchmark prompts\", options: cellOpts(false) },\n      { text: \"As p → 0, mixed distribution converges to P_spec; statistical detection becomes query-prohibitive\", options: cellOpts(false) },\n    ],\n  ];\n\n  slide.addTable(tableData, {\n    x: 0.5, y: 1.1, w: 9.0,\n    colW: [2.3, 3.2, 3.5],\n    border: { pt: 0.5, color: C.slate300 },\n    rowH: [0.4, 0.95, 0.85, 1.0],\n  });\n\n  // Bottom summary bar\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.5, y: 4.6, w: 9.0, h: 0.75,\n    fill: { color: C.darkBg }\n  });\n  slide.addText([\n    { text: \"Verdict: \", options: { bold: true, color: C.red, fontSize: 13, fontFace: FONT_HEADER } },\n    { text: \"No software-only method can provide reliable model integrity guarantees. Each approach has fundamental blind spots that adversarial providers can exploit.\", options: { color: C.textLight, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.75, y: 4.6, w: 8.55, h: 0.75,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n}\n\n// ─── SLIDE 8: TEE Solution ───\nfunction buildSlide8(icons) {\n  const slide = pres.addSlide();\n  slide.background = { color: C.lightBg };\n\n  slide.addText(\"Trusted Execution Environments\", {\n    x: 0.6, y: 0.3, w: 9, h: 0.55,\n    fontSize: 28, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n    align: \"left\", margin: 0\n  });\n  slide.addText(\"Provable Cryptographic Model Integrity\", {\n    x: 0.6, y: 0.82, w: 9, h: 0.35,\n    fontSize: 15, fontFace: FONT_BODY, color: C.greenDark, italic: true,\n    align: \"left\", margin: 0\n  });\n\n  // Left: How TEEs work\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 1.4, w: 4.2, h: 2.6,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 1.4, w: 4.2, h: 0.45,\n    fill: { color: C.green }\n  });\n  slide.addText(\"How TEEs Work\", {\n    x: 0.6, y: 1.4, w: 4.2, h: 0.45,\n    fontSize: 14, fontFace: FONT_HEADER, color: C.white, bold: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  slide.addText([\n    { text: \"Hardware-secured enclaves provide cryptographic attestation of the code and data being executed.\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700, breakLine: true } },\n    { text: \"\", options: { fontSize: 6, breakLine: true } },\n    { text: \"✓  \", options: { color: C.green, fontSize: 11, fontFace: FONT_BODY } },\n    { text: \"Prove specific model weights are loaded\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700, breakLine: true } },\n    { text: \"✓  \", options: { color: C.green, fontSize: 11, fontFace: FONT_BODY } },\n    { text: \"Verify correct inference code is running\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700, breakLine: true } },\n    { text: \"✓  \", options: { color: C.green, fontSize: 11, fontFace: FONT_BODY } },\n    { text: \"Only modest performance overhead\", options: { fontSize: 11, fontFace: FONT_BODY, color: C.slate700, breakLine: true } },\n  ], {\n    x: 0.8, y: 1.95, w: 3.8, h: 1.9,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n\n  // Right: TEE vs Software comparison\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 5.2, y: 1.4, w: 4.3, h: 2.6,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 5.2, y: 1.4, w: 4.3, h: 0.45,\n    fill: { color: C.darkBg }\n  });\n  slide.addText(\"TEE vs. Software Methods\", {\n    x: 5.2, y: 1.4, w: 4.3, h: 0.45,\n    fontSize: 14, fontFace: FONT_HEADER, color: C.textLight, bold: true,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  // Comparison items\n  const comparisons = [\n    { label: \"Provable\", tee: \"Cryptographic proof\", soft: \"Statistical estimates\" },\n    { label: \"Efficient\", tee: \"Modest overhead\", soft: \"Query-prohibitive\" },\n    { label: \"Robust\", tee: \"Adversary-proof\", soft: \"Easily evaded\" },\n  ];\n\n  comparisons.forEach((item, i) => {\n    const rowY = 1.95 + i * 0.6;\n\n    slide.addText(item.label, {\n      x: 5.35, y: rowY, w: 0.9, h: 0.5,\n      fontSize: 10, fontFace: FONT_HEADER, color: C.textDark, bold: true,\n      align: \"left\", valign: \"middle\", margin: 0\n    });\n\n    // TEE value\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 6.3, y: rowY + 0.05, w: 1.5, h: 0.4,\n      fill: { color: C.greenBg }\n    });\n    slide.addText(item.tee, {\n      x: 6.3, y: rowY + 0.05, w: 1.5, h: 0.4,\n      fontSize: 9, fontFace: FONT_BODY, color: C.greenDark, bold: true,\n      align: \"center\", valign: \"middle\", margin: 0\n    });\n\n    // Software value\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 8.0, y: rowY + 0.05, w: 1.3, h: 0.4,\n      fill: { color: C.redBg }\n    });\n    slide.addText(item.soft, {\n      x: 8.0, y: rowY + 0.05, w: 1.3, h: 0.4,\n      fontSize: 9, fontFace: FONT_BODY, color: C.redMuted, bold: true,\n      align: \"center\", valign: \"middle\", margin: 0\n    });\n  });\n\n  // Deployment path card\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 4.3, w: 8.9, h: 0.8,\n    fill: { color: C.white }, shadow: makeCardShadow()\n  });\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 4.3, w: 0.06, h: 0.8,\n    fill: { color: C.green }\n  });\n\n  slide.addText([\n    { text: \"Practical Deployment: \", options: { bold: true, color: C.greenDark, fontSize: 12, fontFace: FONT_HEADER } },\n    { text: \"NVIDIA Confidential Computing on H100 GPUs enables TEE-based attestation today. Unlike Zero-Knowledge Proofs (ZKPs), which are computationally prohibitive for large models, TEEs are practical and deployable now.\", options: { color: C.slate700, fontSize: 11, fontFace: FONT_BODY } },\n  ], {\n    x: 0.85, y: 4.3, w: 8.45, h: 0.8,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n}\n\n// ─── SLIDE 9: Key Takeaways ───\nfunction buildSlide9(icons) {\n  const slide = pres.addSlide();\n  slide.background = { color: C.darkBg };\n\n  // Top accent\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }\n  });\n\n  slide.addText(\"Key Takeaways\", {\n    x: 0.6, y: 0.3, w: 9, h: 0.55,\n    fontSize: 30, fontFace: FONT_HEADER, color: C.textLight, bold: true,\n    align: \"left\", margin: 0\n  });\n  slide.addText(\"Close the Verification Gap with Hardware Attestation\", {\n    x: 0.6, y: 0.82, w: 9, h: 0.35,\n    fontSize: 15, fontFace: FONT_BODY, color: C.accent, italic: true,\n    align: \"left\", margin: 0\n  });\n\n  // 5 takeaway items\n  const takeaways = [\n    { num: \"01\", text: \"Model substitution is economically motivated and practically undetectable via software methods alone.\" },\n    { num: \"02\", text: \"FP8 quantization barely affects benchmark scores — performance drops often fall within error bars.\" },\n    { num: \"03\", text: \"Inference nondeterminism across frameworks and hardware kills log-probability fingerprinting.\" },\n    { num: \"04\", text: \"Randomized substitution and benchmark evasion make statistical detection query-prohibitive.\" },\n    { num: \"05\", text: \"Trusted Execution Environments are the only currently viable path to verifiable LLM APIs.\" },\n  ];\n\n  takeaways.forEach((item, i) => {\n    const itemY = 1.4 + i * 0.65;\n\n    // Number\n    slide.addText(item.num, {\n      x: 0.7, y: itemY, w: 0.6, h: 0.5,\n      fontSize: 20, fontFace: FONT_HEADER, color: i === 4 ? C.green : C.accent, bold: true,\n      align: \"center\", valign: \"middle\", margin: 0\n    });\n\n    // Accent dot\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 1.4, y: itemY + 0.18, w: 0.08, h: 0.15,\n      fill: { color: i === 4 ? C.green : C.accent }\n    });\n\n    // Text\n    slide.addText(item.text, {\n      x: 1.65, y: itemY, w: 7.8, h: 0.5,\n      fontSize: 12, fontFace: FONT_BODY, color: C.textLight,\n      align: \"left\", valign: \"middle\", margin: 0\n    });\n  });\n\n  // Call to action bar\n  slide.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 4.7, w: 8.8, h: 0.6,\n    fill: { color: C.green }\n  });\n  slide.addText([\n    { text: \"Call to Action: \", options: { bold: true, fontSize: 13, fontFace: FONT_HEADER, color: C.white } },\n    { text: \"The community must adopt hardware-based attestation as the standard for LLM API integrity verification.\", options: { fontSize: 12, fontFace: FONT_BODY, color: C.white } },\n  ], {\n    x: 0.85, y: 4.7, w: 8.35, h: 0.6,\n    align: \"left\", valign: \"middle\", margin: 0\n  });\n}\n\n// ─── MAIN ───\nasync function main() {\n  // Pre-render all icons\n  const icons = {\n    shield: await iconToBase64Png(FaShieldAlt, \"#0EA5E9\", 256),\n    chart: await iconToBase64Png(FaChartBar, \"#64748B\", 256),\n    dollar: await iconToBase64Png(FaDollarSign, \"#F59E0B\", 256),\n    lock: await iconToBase64Png(FaLock, \"#10B981\", 256),\n  };\n\n  buildSlide1(icons);\n  buildSlide2(icons);\n  buildSlide3();\n  buildSlide4();\n  buildSlide5();\n  buildSlide6(icons);\n  buildSlide7();\n  buildSlide8(icons);\n  buildSlide9(icons);\n\n  const outPath = path.resolve(\"/app/output/final_deck.pptx\");\n  await pres.writeFile({ fileName: outPath });\n  console.log(\"Presentation saved to:\", outPath);\n}\n\nmain().catch((err) => {\n  console.error(\"Error generating presentation:\", err);\n  process.exit(1);\n});\n", "numLines": 894, "startLine": 1, "totalLines": 894}}

