const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icons
const { FaExclamationTriangle, FaChartBar, FaFingerprint, FaRandom, FaTimesCircle, FaShieldAlt, FaLightbulb, FaDollarSign, FaMicrochip, FaLock } = require("react-icons/fa");

// Color palette - Security/Auditing theme
const C = {
  darkBg: "0F172A",
  darkBgAlt: "1E293B",
  lightBg: "F8FAFC",
  white: "FFFFFF",
  accent: "0EA5E9",
  accentDark: "0284C7",
  red: "EF4444",
  redMuted: "DC2626",
  redBg: "FEF2F2",
  green: "10B981",
  greenDark: "059669",
  greenBg: "ECFDF5",
  amber: "F59E0B",
  amberBg: "FFFBEB",
  slate700: "334155",
  slate600: "475569",
  slate500: "64748B",
  slate400: "94A3B8",
  slate300: "CBD5E1",
  slate200: "E2E8F0",
  slate100: "F1F5F9",
  textDark: "1E293B",
  textLight: "E2E8F0",
  textMuted: "94A3B8",
  cardBg: "FFFFFF",
  tableHeader: "0F172A",
  tableRowAlt: "F1F5F9",
  accentLight: "E0F2FE",
};

const FONT_HEADER = "Trebuchet MS";
const FONT_BODY = "Calibri";

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "ML Security Research";
pres.title = "Auditing Model Substitution in LLM APIs";

// Helper: render icon to base64 PNG
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Helper: create fresh shadow objects (never reuse)
const makeCardShadow = () => ({
  type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.08
});

const makeSubtleShadow = () => ({
  type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.06
});

// ─── SLIDE 1: Title ───
function buildSlide1(icons) {
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Decorative top-right corner accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.5, y: 0, w: 1.5, h: 0.06, fill: { color: C.accent }
  });

  // Main title
  slide.addText("Are You Getting What You Pay For?", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.2,
    fontSize: 40, fontFace: FONT_HEADER, color: C.textLight, bold: true,
    align: "left", margin: 0
  });

  // Subtitle
  slide.addText("Auditing Model Substitution in LLM APIs", {
    x: 0.8, y: 2.2, w: 8.4, h: 0.7,
    fontSize: 22, fontFace: FONT_HEADER, color: C.accent, bold: false,
    align: "left", margin: 0
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 3.1, w: 2.5, h: 0.04, fill: { color: C.accent }
  });

  // Tagline
  slide.addText("Why Software Tests Fail and Hardware Attestation Wins", {
    x: 0.8, y: 3.4, w: 8.4, h: 0.5,
    fontSize: 16, fontFace: FONT_BODY, color: C.slate400, italic: true,
    align: "left", margin: 0
  });

  // Paper reference
  slide.addText("arxiv.org/abs/2504.04715", {
    x: 0.8, y: 4.5, w: 8.4, h: 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.slate500,
    align: "left", margin: 0
  });

  // Shield icon
  slide.addImage({
    data: icons.shield,
    x: 8.2, y: 3.5, w: 1.2, h: 1.2,
    transparency: 15
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325, fill: { color: C.accentDark }
  });
}

// ─── SLIDE 2: Substitution Threat ───
function buildSlide2(icons) {
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("The Model Substitution Problem", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.6,
    fontSize: 28, fontFace: FONT_HEADER, color: C.textDark, bold: true,
    align: "left", margin: 0
  });

  // Subtitle
  slide.addText("Economic Incentives Drive Covert Swaps", {
    x: 0.6, y: 0.85, w: 8.8, h: 0.4,
    fontSize: 16, fontFace: FONT_BODY, color: C.slate500, italic: true,
    align: "left", margin: 0
  });

  // Problem statement card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.5, w: 8.8, h: 0.9,
    fill: { color: C.white }, shadow: makeCardShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.5, w: 0.06, h: 0.9,
    fill: { color: C.accent }
  });
  slide.addText("Commercial LLM API providers charge for specific models but the black-box nature of APIs means users have no guarantee the advertised model is actually being served.", {
    x: 0.85, y: 1.55, w: 8.35, h: 0.8,
    fontSize: 12, fontFace: FONT_BODY, color: C.slate700,
    align: "left", valign: "middle", margin: 0
  });

  // Four substitution type cards - 2x2 grid
  const cardData = [
    { icon: icons.chart, title: "Smaller Model", desc: "8B instead of 70B", color: C.red },
    { icon: icons.chart, title: "Quantized Variant", desc: "FP8/INT8 instead of FP16", color: C.amber },
    { icon: icons.chart, title: "Fine-tuned Version", desc: "Updated or retrained model", color: C.accent },
    { icon: icons.chart, title: "Different Family", desc: "Entirely different architecture", color: C.slate500 },
  ];

  const cardW = 4.1, cardH = 0.85, gapX = 0.4, gapY = 0.2;
  const startX = 0.6, startY = 2.7;

  cardData.forEach((card, i) => {
    const col = i % 2, row = Math.floor(i / 2);
    const cx = startX + col * (cardW + gapX);
    const cy = startY + row * (cardH + gapY);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: C.white }, shadow: makeSubtleShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: 0.06, h: cardH,
      fill: { color: card.color }
    });

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.2, y: cy + 0.18, w: 0.45, h: 0.45,
      fill: { color: card.color }
    });
    slide.addText(String(i + 1), {
      x: cx + 0.2, y: cy + 0.18, w: 0.45, h: 0.45,
      fontSize: 14, fontFace: FONT_HEADER, color: C.white, bold: true,
      align: "center", valign: "middle", margin: 0
    });

    slide.addText(card.title, {
      x: cx + 0.8, y: cy + 0.1, w: 3.0, h: 0.35,
      fontSize: 13, fontFace: FONT_HEADER, color: C.textDark, bold: true,
      align: "left", valign: "bottom", margin: 0
    });
    slide.addText(card.desc, {
      x: cx + 0.8, y: cy + 0.45, w: 3.0, h: 0.3,
